// Preserve the text selection when applying or removing Markdown bold.
export function toggleBold(value, start, end) {
  const selected = value.slice(start, end);
  if (selected.startsWith('**') && selected.endsWith('**') && selected.length > 4) {
    const content = selected.slice(2, -2);
    return { text: value.slice(0, start) + content + value.slice(end), start, end: start + content.length };
  }
  if (start >= 2 && value.slice(start - 2, start) === '**' && value.slice(end, end + 2) === '**') {
    return { text: value.slice(0, start - 2) + selected + value.slice(end + 2), start: start - 2, end: end - 2 };
  }
  const content = selected || 'bold text';
  return { text: value.slice(0, start) + `**${content}**` + value.slice(end), start: start + 2, end: start + 2 + content.length };
}
