import { unified } from 'unified';
import remarkParse from 'remark-parse';
import remarkGfm from 'remark-gfm';

const parser = unified().use(remarkParse).use(remarkGfm);
const identifier = /^[a-z][a-z0-9-]*$/;
const record = value => value && typeof value === 'object' && !Array.isArray(value);
const text = node => node.value ?? (node.children || []).map(text).join('');

export class ExamFormatError extends Error {
  constructor(message, node) {
    const line = node?.position?.start?.line;
    super(`exam.md${line ? `:${line}` : ''}: ${message}`);
    this.name = 'ExamFormatError';
    this.line = line;
  }
}

export function parseExam(markdown) {
  if (typeof markdown !== 'string' || !markdown.trim()) throw new ExamFormatError('The file is empty.');
  const tree = parser.parse(markdown);
  const fail = (message, node = tree) => { throw new ExamFormatError(message, node); };
  const source = nodes => nodes.length
    ? markdown.slice(nodes[0].position.start.offset, nodes.at(-1).position.end.offset).trim() : '';
  const metadata = tree.children.filter(node => node.type === 'html' && /^<!--\s*exam\s*\n/.test(node.value));
  if (metadata.length !== 1) fail('Expected one <!-- exam ... --> metadata block.');
  let settings;
  try { settings = JSON.parse(metadata[0].value.replace(/^<!--\s*exam\s*\n/, '').replace(/-->\s*$/, '')); }
  catch (error) { fail(`Invalid metadata JSON: ${error.message}`, metadata[0]); }
  if (!settings || Array.isArray(settings) || !identifier.test(settings.id || '')) fail('Metadata needs a stable, lowercase exam id.', metadata[0]);
  if (typeof settings.revision !== 'string' || !settings.revision.trim()) fail('Metadata needs a revision.', metadata[0]);
  for (const key of ['answerLimit', 'wordMin', 'wordMax', 'relevanceMax', 'approachMax']) {
    if (!Number.isSafeInteger(settings[key]) || settings[key] < 1) fail(`${key} must be a positive integer.`, metadata[0]);
  }
  if (settings.wordMin > settings.wordMax) fail('wordMin cannot exceed wordMax.', metadata[0]);
  if (!Array.isArray(settings.clarity) || !settings.clarity.length || settings.clarity.some(v =>
    typeof v !== 'string' || !/^(?:0|1|[1-9]\d*\/[1-9]\d*)$/.test(v) || fraction(v) > 1
  ) || new Set(settings.clarity).size !== settings.clarity.length) fail('clarity must contain unique multipliers between 0 and 1.', metadata[0]);
  if (!Array.isArray(settings.approachIds) || !settings.approachIds.length || settings.approachIds.some(id =>
    typeof id !== 'string' || !identifier.test(id)
  ) || new Set(settings.approachIds).size !== settings.approachIds.length) fail('approachIds must contain unique, stable IDs.', metadata[0]);

  const paperBindings = new Map();
  if (settings.papers !== undefined) {
    if (!record(settings.papers) || !Object.keys(settings.papers).length) fail('papers must contain PDF mappings.', metadata[0]);
    const readings = new Set();
    for (const [id, paper] of Object.entries(settings.papers)) {
      if (!identifier.test(id) || !record(paper) || typeof paper.title !== 'string' || !paper.title.trim() ||
          typeof paper.reading !== 'string' || !paper.reading.trim() || !Array.isArray(paper.questions) ||
          !paper.questions.length || paper.questions.some(q => typeof q !== 'string' || !identifier.test(q))) {
        fail(`Invalid PDF mapping "${id}". Include a title, reading, and stable question IDs.`, metadata[0]);
      }
      let url;
      try { url = new URL(paper.pdfUrl); } catch (error) { /* Report the source error below. */ }
      if (typeof paper.pdfUrl !== 'string' || !url || url.protocol !== 'https:' || url.username || url.password) {
        fail(`PDF mapping "${id}" needs an HTTPS URL.`, metadata[0]);
      }
      if (readings.has(paper.reading)) fail(`Duplicate PDF reading "${paper.reading}". Share one mapping across its questions.`, metadata[0]);
      readings.add(paper.reading);
      const linkedPaper = { id, title: paper.title, reading: paper.reading, pdfUrl: paper.pdfUrl };
      for (const questionId of paper.questions) {
        if (paperBindings.has(questionId)) fail(`Question "${questionId}" has multiple PDF mappings.`, metadata[0]);
        paperBindings.set(questionId, linkedPaper);
      }
    }
  }

  const titles = tree.children.filter(node => node.type === 'heading' && node.depth === 1);
  if (titles.length !== 1 || !text(titles[0]).trim()) fail('Expected exactly one # exam title.', titles[1] || tree);
  const sections = [];
  let active;
  for (const node of tree.children) {
    if (node === metadata[0] || node === titles[0]) continue;
    if (node.type === 'heading' && node.depth === 2) {
      active = { heading: text(node).trim(), node, children: [] };
      sections.push(active);
    } else if (active) active.children.push(node);
    else fail('Content must be inside a ## section.', node);
  }
  const singleSection = name => {
    const found = sections.filter(section => section.heading.toLowerCase() === name.toLowerCase());
    if (found.length !== 1) fail(`Expected exactly one ## ${name} section.`, found[1]?.node);
    if (!source(found[0].children)) fail(`${name} cannot be empty.`, found[0].node);
    return found[0];
  };
  const instructions = singleSection('Instructions');
  const approachesSection = singleSection('Approaches');
  const rubric = singleSection('Rubric');
  const lists = approachesSection.children.filter(node => node.type === 'list');
  if (lists.length !== 1 || !lists[0].ordered || lists[0].children.length !== settings.approachIds.length) {
    fail(`Approaches needs one numbered list with ${settings.approachIds.length} items.`, approachesSection.node);
  }
  const approaches = lists[0].children.map((node, i) => {
    const label = source(node.children);
    if (!label) fail('Approach labels cannot be empty.', node);
    return { id: settings.approachIds[i], label };
  });
  const ids = new Set();
  const questions = [];
  for (const section of sections) {
    if ([instructions, approachesSection, rubric].includes(section)) continue;
    const match = /^Question\s+([a-z][a-z0-9-]*)\s+\(([^()]+)\)$/.exec(section.heading);
    if (!match) fail('Use ## Question stable-id (reading label), or a named section.', section.node);
    const [, id, reading] = match;
    if (ids.has(id)) fail(`Duplicate question ID "${id}". Keep IDs unique even when reading labels repeat.`, section.node);
    ids.add(id);
    const planHeadings = section.children.filter(node => node.type === 'heading' && node.depth === 3 && text(node).trim().toLowerCase() === 'ai plan');
    if (planHeadings.length !== 1) fail('Each question needs exactly one ### AI Plan heading.', planHeadings[1] || section.node);
    const split = section.children.indexOf(planHeadings[0]);
    const prompt = source(section.children.slice(0, split));
    const plan = source(section.children.slice(split + 1));
    if (!prompt) fail(`Question "${id}" has no question text.`, section.node);
    if (!plan) fail(`Question "${id}" has no AI plan.`, planHeadings[0]);
    const question = { id, reading: reading.trim(), prompt, plan, number: questions.length + 1 };
    if (settings.papers !== undefined) {
      const paper = paperBindings.get(id);
      if (!paper) fail(`Question "${id}" needs a PDF mapping.`, section.node);
      if (paper.reading !== question.reading) fail(`PDF reading "${paper.reading}" does not match "${question.reading}" for question "${id}".`, section.node);
      question.paper = paper;
    }
    questions.push(question);
  }
  if (questions.length < settings.answerLimit) fail(`Need at least ${settings.answerLimit} questions.`);
  for (const id of paperBindings.keys()) {
    if (!ids.has(id)) fail(`PDF mapping refers to missing question "${id}".`, metadata[0]);
  }
  return { ...settings, title: text(titles[0]), instructions: source(instructions.children),
    aiUsage: source(approachesSection.children), rubric: source(rubric.children), approaches, questions };
}

export function fraction(value) {
  const [n, d = 1] = String(value).split('/').map(Number);
  return n / d;
}

export function countWords(value) {
  return plainMarkdown(value).trim().match(/\S+/gu)?.length || 0;
}

export function plainMarkdown(markdown) {
  const walk = node => {
    if (node.type === 'break') return '\n';
    if (node.type === 'html') return '';
    if (node.type === 'image') return node.alt || '';
    const value = node.value ?? (node.children || []).map(walk).join('');
    return ['paragraph', 'heading', 'listItem', 'code'].includes(node.type) ? `${value}\n\n` : value;
  };
  return walk(parser.parse(markdown)).trim();
}
