import { plainMarkdown } from './parseExam.mjs';

export const storageKey = exam => `cmsc839e:exam:${exam.id}:draft:v1`;
const record = value => value && typeof value === 'object' && !Array.isArray(value);
const validId = value => typeof value === 'string' && /^[a-z][a-z0-9-]*$/.test(value);

export function emptyDraft(exam) {
  return { schemaVersion: 1, examId: exam.id, revision: exam.revision, selected: [], answers: {}, savedAt: null };
}

export function questionSnapshot(question, exam) {
  return JSON.stringify({ prompt: question.prompt, approaches: exam.approaches });
}

export function validateDraft(value, exam) {
  if (!record(value) || value.schemaVersion !== 1 || value.examId !== exam.id) throw new Error('This backup belongs to a different exam or uses an unsupported format.');
  if (!record(value.answers) ||
      !Array.isArray(value.selected) || value.selected.some(id => !validId(id)) ||
      new Set(value.selected).size !== value.selected.length || value.selected.length > exam.answerLimit) throw new Error('This draft has invalid student or selection data.');
  const answers = {};
  for (const [id, answer] of Object.entries(value.answers)) {
    if (!validId(id) || !record(answer) || typeof answer.text !== 'string' || answer.text.length > 200000 ||
        !Array.isArray(answer.approaches) || answer.approaches.some(a => !validId(a)) ||
        new Set(answer.approaches).size !== answer.approaches.length ||
        (answer.snapshot != null && (typeof answer.snapshot !== 'string' || answer.snapshot.length > 200000))) throw new Error(`Invalid answer in backup: ${id}.`);
    // Retain answers for removed questions: content updates must never silently delete work.
    answers[id] = { text: answer.text, approaches: [...answer.approaches], snapshot: answer.snapshot || '' };
  }
  // Older backups may contain a name; accept them and omit that retired field.
  return { ...emptyDraft(exam), selected: [...value.selected], answers,
    revision: typeof value.revision === 'string' ? value.revision : '',
    savedAt: typeof value.savedAt === 'string' ? value.savedAt : null };
}

export function exportProblems(draft, exam) {
  const problems = [];
  if (draft.selected.length !== exam.answerLimit) problems.push(`Select ${exam.answerLimit} questions for submission before exporting the PDF.`);
  for (const id of draft.selected) {
    const question = exam.questions.find(q => q.id === id);
    if (!question) { problems.push('A selected question was removed in an exam update. Review your selection.'); continue; }
    const answer = draft.answers[id];
    const label = `Question ${String(question.number).padStart(2, '0')}`;
    if (!answer?.text || !plainMarkdown(answer.text).trim()) problems.push(`${label} needs an answer.`);
    if (!answer?.approaches.length) problems.push(`${label}: select the approaches you used.`);
    if (answer?.approaches.some(a => !exam.approaches.some(option => option.id === a))) problems.push(`${label}: review the updated approach options.`);
    if (answer?.snapshot && answer.snapshot !== questionSnapshot(question, exam)) problems.push(`${label} changed since your draft. Review the updated question.`);
  }
  return problems;
}
