import React, { useEffect, useMemo, useRef, useState } from 'react';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { FiArrowLeft, FiCheck, FiChevronDown, FiCopy, FiDownload, FiExternalLink, FiEye, FiEyeOff, FiPrinter, FiUpload } from 'react-icons/fi';
import { countWords, parseExam, plainMarkdown } from './parseExam.mjs';
import { emptyDraft, exportProblems, questionSnapshot, storageKey, validateDraft } from './draft.mjs';
import { toggleBold } from './formatAnswer.mjs';
import './Midterm.css';

const publicBase = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
const pad = value => String(value).padStart(2, '0');
const markdownComponents = { a: ({ node, children, ...props }) => <a {...props} target="_blank" rel="noreferrer">{children}</a> };
const instructionComponents = { ...markdownComponents, h3: ({ children }) => <h2 className="exam-section-title">{children}</h2> };
const Content = ({ children, components = markdownComponents }) => <Markdown remarkPlugins={[remarkGfm]} components={components} skipHtml>{children}</Markdown>;

function PaperReference({ question, print = false }) {
  const paper = question.paper;
  if (!paper) return <span className="exam-reading">{question.reading}</span>;
  const words = paper.title.trim().split(/\s+/);
  const shortTitle = words.slice(0, 3).join(' ').replace(/[,:;!?]$/, '') + (words.length > 3 ? '…' : '');
  return <>
    <a className={print ? undefined : 'exam-reading'} href={paper.pdfUrl} target="_blank" rel="noopener noreferrer" aria-label={`Open ${question.reading}: ${paper.title} (PDF)`} title={paper.title}>
      {question.reading}{!print && <FiExternalLink aria-hidden="true" />}
    </a>{' '}<span className="exam-paper-title" title={paper.title}>{shortTitle}</span>
  </>;
}

async function copyText(value) {
  // Embedded browsers may expose Clipboard API without bridging it to their
  // host clipboard. A native copy event also supports those environments.
  const focused = document.activeElement;
  const field = document.createElement('textarea');
  field.value = value;
  field.readOnly = true;
  field.style.cssText = 'position:fixed;top:0;left:0;opacity:0;pointer-events:none';
  document.body.appendChild(field);
  field.focus({ preventScroll: true });
  field.select();
  let copied = false;
  try { copied = document.execCommand('copy'); } catch (error) { /* Use Clipboard API below. */ }
  field.remove();
  focused?.focus({ preventScroll: true });
  if (!copied) await navigator.clipboard.writeText(value);
}

function download(content, filename) {
  const url = URL.createObjectURL(new Blob([content], { type: 'application/json;charset=utf-8' }));
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function backup(draft, exam, suffix = '') {
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  download(JSON.stringify({ ...draft, savedAt: new Date().toISOString() }, null, 2), `${exam.id}${suffix}-${stamp}.json`);
}

function readSaved(exam) {
  let raw = null;
  try {
    raw = localStorage.getItem(storageKey(exam));
    return { draft: raw ? validateDraft(JSON.parse(raw), exam) : emptyDraft(exam), raw, error: '' };
  } catch (error) {
    return { draft: emptyDraft(exam), raw, error: raw
      ? 'The saved draft could not be read. Download the saved data before starting a new draft.'
      : 'Browser storage is unavailable. Download a backup to keep your work.' };
  }
}

export default function Midterm() {
  const [exam, setExam] = useState(null);
  const [error, setError] = useState('');
  useEffect(() => {
    const controller = new AbortController();
    fetch(`${publicBase}/exam.md`, { signal: controller.signal, cache: 'no-cache' })
      .then(response => { if (!response.ok) throw new Error(`Could not load exam.md (${response.status}).`); return response.text(); })
      .then(markdown => setExam(parseExam(markdown)))
      .catch(reason => { if (reason.name !== 'AbortError') setError(reason.message); });
    return () => controller.abort();
  }, []);
  if (error) return <main className="exam-page exam-load"><h1>Could not open the exam</h1><p role="alert">{error}</p></main>;
  if (!exam) return <main className="exam-page exam-load" aria-busy="true">Loading exam…</main>;
  return <ExamWorkspace key={exam.id} exam={exam} />;
}

function ExamWorkspace({ exam }) {
  const initial = useMemo(() => readSaved(exam), [exam]);
  const [draft, setDraft] = useState(initial.draft);
  const [storageError, setStorageError] = useState(initial.error);
  const [blocked, setBlocked] = useState(Boolean(initial.raw && initial.error));
  const [externalDraft, setExternalDraft] = useState(null);
  const [saveStatus, setSaveStatus] = useState(initial.raw && !initial.error ? 'Saved in this browser' : '');
  const [notice, setNotice] = useState('');
  const [exportErrors, setExportErrors] = useState([]);
  const [printDraft, setPrintDraft] = useState(null);
  const [plans, setPlans] = useState(() => Object.fromEntries(exam.questions.map(q => [q.id, true])));
  const [activeSection, setActiveSection] = useState('instructions');
  const restoreInput = useRef(null);
  const exportNotice = useRef(null);
  const lastWritten = useRef(initial.raw);
  const current = useRef({ draft, blocked, externalDraft });
  current.current = { draft, blocked, externalDraft };

  useEffect(() => {
    const originalTitle = document.title;
    document.title = exam.title;
    return () => { document.title = originalTitle; };
  }, [exam.title]);

  useEffect(() => {
    const ids = ['instructions', 'rubric', ...exam.questions.map(question => `question-${question.id}`)];
    const page = document.querySelector('.exam-page');
    const sidebar = document.querySelector('.exam-sidebar');
    const toolbar = document.querySelector('.exam-selection-bar');
    let frame;
    const navHeight = () => window.matchMedia('(max-width: 600px)').matches ? sidebar.offsetHeight : 0;
    const update = () => {
      const threshold = navHeight() + toolbar.offsetHeight + 26;
      let active = ids[0];
      for (const id of ids) {
        const element = document.getElementById(id);
        if (element && element.getBoundingClientRect().top <= threshold) active = id;
      }
      setActiveSection(active);
    };
    const schedule = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(update);
    };
    const measure = () => {
      page.style.setProperty('--exam-nav-offset', `${navHeight()}px`);
      page.style.setProperty('--exam-toolbar-height', `${toolbar.offsetHeight}px`);
      schedule();
    };
    const observer = new ResizeObserver(measure);
    for (const element of [document.querySelector('.exam-main'), sidebar, toolbar]) observer.observe(element);
    window.addEventListener('scroll', schedule, { passive: true });
    window.addEventListener('resize', measure);
    measure();
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      window.removeEventListener('scroll', schedule);
      window.removeEventListener('resize', measure);
    };
  }, [exam]);

  useEffect(() => {
    if (blocked || externalDraft) return undefined;
    setSaveStatus('Saving…');
    const persist = () => {
      try {
        const raw = JSON.stringify({ ...current.current.draft, savedAt: new Date().toISOString() });
        localStorage.setItem(storageKey(exam), raw);
        lastWritten.current = raw;
        setSaveStatus('Saved in this browser');
        setStorageError('');
        return true;
      } catch (error) {
        setSaveStatus('');
        setStorageError('Autosave is unavailable. Download a backup to keep your work.');
        return false;
      }
    };
    const timer = setTimeout(persist, 250);
    const onExit = event => {
      if (!current.current.blocked && !current.current.externalDraft && !persist() && event.type === 'beforeunload') {
        event.preventDefault(); event.returnValue = '';
      }
    };
    window.addEventListener('pagehide', onExit);
    window.addEventListener('beforeunload', onExit);
    return () => {
      clearTimeout(timer);
      window.removeEventListener('pagehide', onExit);
      window.removeEventListener('beforeunload', onExit);
    };
  }, [draft, exam, blocked, externalDraft]);

  useEffect(() => {
    const onStorage = event => {
      if (event.key !== storageKey(exam) || !event.newValue || event.newValue === lastWritten.current) return;
      try { setExternalDraft(validateDraft(JSON.parse(event.newValue), exam)); }
      catch (error) { setStorageError('Another tab changed the saved data. Download a backup of this tab’s work.'); }
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, [exam]);

  useEffect(() => {
    if (!printDraft) return undefined;
    const oldTitle = document.title;
    document.title = exam.title;
    const afterPrint = () => { document.title = oldTitle; setPrintDraft(null); };
    window.addEventListener('afterprint', afterPrint);
    const frame = requestAnimationFrame(() => { try { window.print(); } finally { afterPrint(); } });
    return () => { cancelAnimationFrame(frame); window.removeEventListener('afterprint', afterPrint); document.title = oldTitle; };
  }, [printDraft, exam.title]);

  const updateAnswer = (question, update) => {
    setDraft(previous => {
      const old = previous.answers[question.id] || { text: '', approaches: [], snapshot: questionSnapshot(question, exam) };
      return { ...previous, answers: { ...previous.answers, [question.id]: { ...old, ...update(old) } } };
    });
    setExportErrors([]);
  };
  const selectQuestion = id => {
    if (!draft.selected.includes(id) && draft.selected.length >= exam.answerLimit) {
      setNotice(`You have selected ${exam.answerLimit} questions. Deselect one before choosing another.`); return;
    }
    setDraft(previous => ({ ...previous, selected: previous.selected.includes(id)
      ? previous.selected.filter(value => value !== id) : [...previous.selected, id] }));
    setExportErrors([]); setNotice('');
  };
  const restore = async event => {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) return;
    try {
      if (file.size > 2 * 1024 * 1024) throw new Error('This file is too large to be an exam backup.');
      const restored = validateDraft(JSON.parse(await file.text()), exam);
      if (blocked) throw new Error('Download the unreadable saved data before restoring a backup.');
      const hasWork = draft.selected.length || Object.values(draft.answers).some(answer => answer.text || answer.approaches.length);
      if (hasWork) backup(draft, exam, '-before-restore');
      setDraft(restored); setExternalDraft(null); setExportErrors([]);
      setNotice(hasWork ? 'Backup restored. Your previous draft was downloaded first.' : 'Backup restored.');
    } catch (error) { setNotice(error.message); }
  };
  const allHidden = exam.questions.every(q => !plans[q.id]);
  const removedSelections = draft.selected.filter(id => !exam.questions.some(q => q.id === id));
  const print = () => {
    const problems = exportProblems(draft, exam);
    setExportErrors(problems);
    if (problems.length) {
      requestAnimationFrame(() => {
        exportNotice.current?.focus({ preventScroll: true });
        exportNotice.current?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
      });
    } else setPrintDraft(draft);
  };

  return <div className="exam-page">
    <div className="exam-screen">
      <div className="exam-topbar">
        <a href={`${publicBase}/`} className="exam-course-link"><FiArrowLeft aria-hidden="true" /> CMSC839E</a>
        <div className="exam-topbar-actions">
          <button onClick={() => backup(draft, exam)}><FiDownload aria-hidden="true" /> Backup</button>
          <button onClick={() => restoreInput.current.click()}><FiUpload aria-hidden="true" /> Restore</button>
          <input ref={restoreInput} type="file" accept=".json,application/json" onChange={restore} hidden aria-label="Restore a draft backup" />
        </div>
      </div>
      <div className="exam-layout">
      <ExamNavigation exam={exam} selected={draft.selected} active={activeSection} onNavigate={setActiveSection} />
      <main className="exam-main">
        <header className="exam-header" id="instructions" tabIndex={-1}>
          <p className="exam-term">CMSC839E · 2026</p>
          <h1>{exam.title.replace(/^CMSC839E\s+/, '').replace(/\s*\(\d{4}\)$/, '')}<span className="exam-title-dot">.</span></h1>
          <p className="exam-version-note">This is not the final version.</p>
          <div className="exam-intro"><Content components={instructionComponents}>{exam.instructions}</Content></div>
          <details className="exam-ai-usage" open><summary><h2 className="exam-section-title">AI usage</h2><FiChevronDown aria-hidden="true" /></summary><Content>{exam.aiUsage}</Content></details>
          <details className="exam-rubric" id="rubric" tabIndex={-1} open><summary><h2 className="exam-section-title">Grading rubric</h2><FiChevronDown aria-hidden="true" /></summary><Content>{exam.rubric}</Content></details>
        </header>
        {storageError && <div className="exam-notice" role="alert">{storageError}{blocked && <button onClick={() => {
          download(initial.raw, `${exam.id}-unreadable-saved-data.json`); setBlocked(false); setStorageError('');
        }}>Download saved data and continue</button>}</div>}
        {externalDraft && <div className="exam-notice" role="alert">Another tab saved a newer draft. This tab’s autosave is paused. <button onClick={() => {
          backup(draft, exam, '-before-tab-restore'); setDraft(externalDraft); setExternalDraft(null); setNotice('Newer draft loaded. This tab’s previous draft was downloaded.');
        }}>Load newer draft</button></div>}
        {notice && <div className="exam-notice" role="status">{notice}<button className="exam-notice-dismiss" onClick={() => setNotice('')} aria-label="Dismiss message">×</button></div>}
        {removedSelections.length > 0 && <div className="exam-notice" role="alert">{removedSelections.length} selected question(s) were removed from the exam. Your answers remain in your backup. <button onClick={() => setDraft(previous => ({ ...previous, selected: previous.selected.filter(id => !removedSelections.includes(id)) }))}>Update selection</button></div>}
        <div className="exam-selection-bar">
          <div className="exam-selection-summary">
            <div className="exam-selection-count"><strong>{draft.selected.length} / {exam.answerLimit}</strong><span>selected for submission</span></div>
            <span className="exam-save-status" role="status">{saveStatus === 'Saved in this browser' && <FiCheck aria-hidden="true" />}{saveStatus}</span>
          </div>
          <div className="exam-actions">
            <button className="exam-hide-all" aria-label={allHidden ? 'Show all AI plans' : 'Hide all AI plans'} onClick={() => setPlans(Object.fromEntries(exam.questions.map(q => [q.id, allHidden])))}>
              {allHidden ? <FiEye aria-hidden="true" /> : <FiEyeOff aria-hidden="true" />}
              <span>{allHidden ? 'Show all AI plans' : 'Hide all AI plans'}</span>
            </button>
            <button className="exam-export" onClick={print}><FiPrinter aria-hidden="true" /><span>Export PDF</span></button>
          </div>
        </div>
        {exportErrors.length > 0 && <div ref={exportNotice} className="exam-notice exam-export-notice" role="alert" tabIndex={-1}><ul>{exportErrors.map((message, i) => <li key={i}>{message}</li>)}</ul></div>}
        <div className="exam-questions">
          {exam.questions.map(question => <Question key={question.id} question={question} exam={exam}
            answer={draft.answers[question.id] || { text: '', approaches: [] }} selected={draft.selected.includes(question.id)}
            onSelect={() => selectQuestion(question.id)} planVisible={plans[question.id]}
            onTogglePlan={() => setPlans(previous => ({ ...previous, [question.id]: !previous[question.id] }))}
            onAnswer={update => updateAnswer(question, update)} />)}
        </div>
        <footer className="exam-footer"><span>Drafts are saved in this browser. Download a backup to move devices.</span><span>Export your selected answers as a PDF and submit it to Canvas.</span></footer>
      </main>
      </div>
    </div>
    <PrintView exam={exam} draft={printDraft || draft} />
  </div>;
}

function ExamNavigation({ exam, selected, active, onNavigate }) {
  const navigate = (event, id) => {
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return;
    const target = document.getElementById(id);
    if (!target) return;
    event.preventDefault();
    if (target.tagName === 'DETAILS') target.open = true;
    target.focus({ preventScroll: true });
    target.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
    window.history.replaceState(null, '', `#${id}`);
    onNavigate(id);
  };
  return <aside className="exam-sidebar">
    <nav className="exam-navigation" aria-label="Exam navigation">
      <div className="exam-section-links">
        {[['instructions', 'Instructions'], ['rubric', 'Rubric']].map(([id, label]) =>
          <a key={id} href={`#${id}`} onClick={event => navigate(event, id)} aria-current={active === id ? 'location' : undefined}>{label}</a>
        )}
      </div>
      <div className="exam-question-links">
        {exam.questions.map(question => {
          const id = `question-${question.id}`;
          return <a key={id} href={`#${id}`} onClick={event => navigate(event, id)}
            aria-current={active === id ? 'location' : undefined}
            aria-label={`Question ${pad(question.number)}, ${question.reading}${selected.includes(question.id) ? ', selected for submission' : ''}`}>
            <span>{pad(question.number)}</span><span className="exam-nav-reading">{question.reading}</span>
            {selected.includes(question.id) && <span className="exam-nav-selected" aria-hidden="true" />}
          </a>;
        })}
      </div>
    </nav>
  </aside>;
}

function Question({ question, exam, answer, selected, onSelect, planVisible, onTogglePlan, onAnswer }) {
  const [copyStatus, setCopyStatus] = useState('');
  const copyTimer = useRef(null);
  const answerInput = useRef(null);
  useEffect(() => () => clearTimeout(copyTimer.current), []);
  const changed = answer.snapshot && answer.snapshot !== questionSnapshot(question, exam);
  const words = useMemo(() => countWords(answer.text), [answer.text]);
  const copyPlan = async () => {
    try { await copyText(plainMarkdown(question.plan)); setCopyStatus('Copied'); }
    catch (error) { setCopyStatus('Could not copy'); }
    clearTimeout(copyTimer.current); copyTimer.current = setTimeout(() => setCopyStatus(''), 2200);
  };
  const bold = () => {
    const input = answerInput.current;
    if (!input) return;
    const result = toggleBold(input.value, input.selectionStart, input.selectionEnd);
    onAnswer(() => ({ text: result.text }));
    requestAnimationFrame(() => {
      input.focus({ preventScroll: true });
      input.setSelectionRange(result.start, result.end);
    });
  };
  return <article className={`exam-question${selected ? ' exam-question-selected' : ''}`} id={`question-${question.id}`} aria-labelledby={`heading-${question.id}`} tabIndex={-1}>
    <div className="exam-question-top">
      <h2 id={`heading-${question.id}`}><span className="exam-number">{pad(question.number)}</span><PaperReference question={question} /></h2>
      <label className="exam-select"><input type="checkbox" checked={selected} onChange={onSelect} aria-label={`Select question ${pad(question.number)} for submission`} /><span>{selected ? 'Selected for submission' : 'Select for submission'}</span></label>
    </div>
    <div className="exam-prompt"><Content>{question.prompt}</Content></div>
    {changed && <div className="exam-notice" role="alert">This question or its approach options changed since your draft. <button onClick={() => onAnswer(() => ({ snapshot: questionSnapshot(question, exam) }))}>I have reviewed the update</button></div>}
    <section className={`exam-plan${planVisible ? ' is-open' : ''}`} aria-label={`AI-generated plan for question ${question.number}`}>
      <div className="exam-plan-toolbar">
        <button className="exam-plan-toggle" onClick={onTogglePlan} aria-expanded={planVisible} aria-controls={`plan-${question.id}`}>
          <FiChevronDown aria-hidden="true" /><span>AI-generated plan</span>
        </button>
        <div className="exam-plan-actions"><button onClick={onTogglePlan} aria-label={`${planVisible ? 'Hide' : 'Show'} AI plan for question ${pad(question.number)}`}>{planVisible ? <FiEyeOff aria-hidden="true" /> : <FiEye aria-hidden="true" />}{planVisible ? 'Hide' : 'Show'}</button><button onClick={copyPlan} aria-label={`Copy AI plan for question ${pad(question.number)}`}><FiCopy aria-hidden="true" />{copyStatus || 'Copy'}</button></div>
      </div>
      {planVisible && <div className="exam-plan-content" id={`plan-${question.id}`}><Content>{question.plan}</Content></div>}
      <span className="exam-sr-only" role="status">{copyStatus}</span>
    </section>
    <section className="exam-answer" aria-labelledby={`answer-heading-${question.id}`}>
      <div className="exam-answer-heading">
        <h3 id={`answer-heading-${question.id}`}>Your answer</h3>
        <span className={`exam-word-count${words && (words < exam.wordMin || words > exam.wordMax) ? ' outside-range' : ''}`}>{words} words<span> / {exam.wordMin}–{exam.wordMax}</span></span>
      </div>
      <div className="exam-answer-content" id={`answer-${question.id}`}>
        <div className="exam-format-toolbar" role="toolbar" aria-label={`Answer formatting for question ${pad(question.number)}`}>
          <button className="exam-bold-button" onMouseDown={event => event.preventDefault()} onClick={bold} aria-label={`Bold text in question ${pad(question.number)}`} title="Bold (⌘/Ctrl+B)"><strong>B</strong></button>
        </div>
        <textarea ref={answerInput} aria-label={`Your answer to question ${pad(question.number)}`} value={answer.text} onChange={event => onAnswer(() => ({ text: event.target.value }))} onKeyDown={event => {
          if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'b') { event.preventDefault(); bold(); }
        }} maxLength={200000} spellCheck="true" placeholder="Write your research plan. Use **bold** for emphasis…" />
        <fieldset className="exam-approaches"><legend>Approaches used</legend>{exam.approaches.map(option => <label key={option.id}><input type="checkbox" checked={answer.approaches.includes(option.id)} onChange={() => onAnswer(old => ({ approaches: old.approaches.includes(option.id) ? old.approaches.filter(id => id !== option.id) : [...old.approaches, option.id] }))} /><Content>{option.label}</Content></label>)}</fieldset>
      </div>
    </section>
    <Grading label={`Grading for question ${pad(question.number)}`} />
  </article>;
}

function Grading({ label }) {
  const box = <span className="exam-grade-box" aria-hidden="true" />;
  return <div className="exam-grading" role="group" aria-label={label}>
    <strong className="exam-grading-label">Grading (only for graders)</strong>
    <div className="exam-grade-equation">
      <span className="exam-grade-sum"><span>(</span><span className="exam-grade-term">Relevance {box}</span><span>+</span><span className="exam-grade-term">Approach {box}</span><span>)</span></span>
      <span className="exam-grade-factor"><span>×</span><span className="exam-grade-term">Clarity {box}</span></span>
      <span className="exam-grade-factor"><span>=</span><span className="exam-grade-term">Total {box}</span></span>
    </div>
  </div>;
}

function PrintView({ exam, draft }) {
  const problems = exportProblems(draft, exam);
  return <div className="exam-print">
    <header><h1>{exam.title}</h1></header>
    <section className="exam-print-rubric"><h2>Grading rubric</h2><Content>{exam.rubric}</Content></section>
    {problems.length ? <div className="exam-print-problems"><h2>Before exporting</h2><ul>{problems.map((problem, i) => <li key={i}>{problem}</li>)}</ul></div> :
      exam.questions.filter(q => draft.selected.includes(q.id)).map(question => {
        const answer = draft.answers[question.id];
        return <article className="exam-printed-question" key={question.id}>
          <div className="exam-print-question-heading"><h2>Question {pad(question.number)} · <PaperReference question={question} print /></h2><p>Word count: {countWords(answer.text)}</p></div>
          <div className="exam-print-prompt"><Content>{question.prompt}</Content></div>
          <div className="exam-print-answer"><Content>{answer.text}</Content></div>
          <div className="exam-print-approaches"><h3>Approaches used</h3><ul>{exam.approaches.filter(option => answer.approaches.includes(option.id)).map(option => <li key={option.id}><Content>{option.label}</Content></li>)}</ul></div>
          <Grading label={`Grading for printed question ${pad(question.number)}`} />
        </article>;
      })}
  </div>;
}
